		for (LmdbNativeKernelIr.Node node : lowered.kernel.pipeline) {
			if (node instanceof LmdbNativeKernelIr.EnumerateAdjKeys keys) {
				if (keys.wildcard || keys.valueCol >= 0 || keys.ctxActive()) {
					return null;
				}
				LmdbNativeKernelBindings.AdjacencyRequest request = lowered.bindings.adjacencies[keys.adjacency];
				return root.p.isConstant() && root.p.constant == request.predicate ? request : null;
			}
		}
		return null;
